import numpy as np
from mg_np import extract_faces, apply_A, smooth, dense_solve

def coarsen_agg(ex,ey):
    n=ex.shape[0]; nc=n//2
    exc=np.empty((nc,nc+1),dtype=ex.dtype)
    exc[:,0]=ex[0::2,0]+ex[1::2,0]
    exc[:,nc]=ex[0::2,n]+ex[1::2,n]
    exc[:,1:-1]=ex[0::2,2:n:2]+ex[1::2,2:n:2]
    eyc=np.empty((nc+1,nc),dtype=ey.dtype)
    eyc[0,:]=ey[0,0::2]+ey[0,1::2]
    eyc[nc,:]=ey[n,0::2]+ey[n,1::2]
    eyc[1:-1,:]=ey[2:n:2,0::2]+ey[2:n:2,1::2]
    return exc,eyc

def build_levels_agg(ex,ey):
    lev=[(ex,ey,ex[:,:-1]+ex[:,1:]+ey[:-1,:]+ey[1:,:])]
    while True:
        n=ex.shape[0]
        if n<=8 or n%2: break
        ex,ey=coarsen_agg(ex,ey)
        lev.append((ex,ey,ex[:,:-1]+ex[:,1:]+ey[:-1,:]+ey[1:,:]))
    return lev

def prolong_agg(ec):
    n=ec.shape[0]*2
    u=np.empty((n,n,ec.shape[2]),dtype=ec.dtype)
    u[0::2,0::2]=ec; u[0::2,1::2]=ec; u[1::2,0::2]=ec; u[1::2,1::2]=ec
    return u

def restrict_agg(u):
    n=u.shape[0]; m=n//2
    c=u[0::2,0::2]+u[0::2,1::2]+u[1::2,0::2]+u[1::2,1::2]
    return c

def vcycle(lev,idx,b,x=None,pre=1,post=1):
    ex,ey,d=lev[idx]
    if x is None: x=np.zeros_like(b)
    if idx==len(lev)-1: return dense_solve(ex,ey,b)
    for _ in range(pre):
        smooth(x,b,ex,ey,d,0); smooth(x,b,ex,ey,d,1)
    r=b-apply_A(x,ex,ey,d)
    ec=vcycle(lev,idx+1,restrict_agg(r))
    x=x+prolong_agg(ec)
    for _ in range(post):
        smooth(x,b,ex,ey,d,1); smooth(x,b,ex,ey,d,0)
    return x

def solve_mg(ex,ey,b,tol=1e-11,maxcycle=100,verbose=False,pre=1,post=1):
    lev=build_levels_agg(ex,ey)
    sh=b.shape; b=b.reshape(ex.shape[0],ex.shape[0],-1); x=np.zeros_like(b)
    bn=np.maximum(np.linalg.norm(b,axis=(0,1)),1e-300)
    for it in range(1,maxcycle+1):
        x=vcycle(lev,0,b,x,pre,post)
        r=b-apply_A(x,*lev[0])
        rel=np.linalg.norm(r,axis=(0,1))/bn
        if verbose: print('cycle',it,rel.max())
        if np.max(rel)<tol: return x.reshape(sh),it,rel
    return x.reshape(sh),it,rel
